let file = """{"version":3,"file":"useFeatureUsageTracker-ofEKK-lB.js","names":[],"sources":["../../src/platform/surveys/surveyRegistry.ts","../../src/platform/surveys/useFeatureUsageTracker.ts"],"sourcesContent":["import type { FeatureSurveyConfig } from './useSurveyEligibility'\n\n/**\n * Registry of all feature surveys.\n * Add new surveys here when targeting specific features for feedback.\n */\nexport const FEATURE_SURVEYS: Record<string, FeatureSurveyConfig> = {\n  'node-search': {\n    featureId: 'node-search',\n    typeformId: 'goZLqjKL',\n    triggerThreshold: 3,\n    delayMs: 5000\n  },\n  'queue-progress-overlay': {\n    featureId: 'queue-progress-overlay',\n    typeformId: 'HZ5saxry',\n    triggerThreshold: 16,\n    delayMs: 5000\n  },\n  'error-panel': {\n    featureId: 'error-panel',\n    typeformId: 'iFp4p4mV',\n    triggerThreshold: 3,\n    presentation: 'inline-cta'\n  },\n  'example-workflows': {\n    featureId: 'example-workflows',\n    typeformId: 'OnKJQYLE',\n    triggerThreshold: 3,\n    delayMs: 5000\n  }\n}\n\nexport function getSurveyConfig(\n  featureId: string\n): FeatureSurveyConfig | undefined {\n  return FEATURE_SURVEYS[featureId]\n}\n\nexport function getEnabledSurveys(): FeatureSurveyConfig[] {\n  return Object.values(FEATURE_SURVEYS).filter(\n    (config) => config.enabled !== false\n  )\n}\n\n/**\n * Surveys that should auto-popup via the global controller.\n * Inline-CTA surveys are excluded because their feature-site renders them.\n */\nexport function getFloatingSurveys(): FeatureSurveyConfig[] {\n  return getEnabledSurveys().filter(\n    (config) => (config.presentation ?? 'floating') === 'floating'\n  )\n}\n","import { useStorage } from '@vueuse/core'\nimport { computed } from 'vue'\n\ninterface FeatureUsage {\n  useCount: number\n  firstUsed: number\n  lastUsed: number\n}\n\ntype FeatureUsageRecord = Partial<Record<string, FeatureUsage>>\n\nconst STORAGE_KEY = 'Comfy.FeatureUsage'\nconst pendingUsage = new Map<string, FeatureUsage>()\n\nfunction latestUsage(\n  storedUsage: FeatureUsage | undefined,\n  currentUsage: FeatureUsage | undefined\n) {\n  if (!storedUsage) return currentUsage\n  if (!currentUsage) return storedUsage\n  return storedUsage.useCount >= currentUsage.useCount\n    ? storedUsage\n    : currentUsage\n}\n\nfunction incrementUsage(\n  usage: FeatureUsage | undefined,\n  now: number\n): FeatureUsage {\n  return {\n    useCount: (usage?.useCount ?? 0) + 1,\n    firstUsed: usage?.firstUsed ?? now,\n    lastUsed: now\n  }\n}\n\nfunction applyPendingUsage(usageData: FeatureUsageRecord) {\n  return {\n    ...usageData,\n    ...Object.fromEntries(\n      [...pendingUsage].map(([featureId, usage]) => [\n        featureId,\n        latestUsage(usageData[featureId], usage)\n      ])\n    )\n  }\n}\n\nfunction persistUsageData(\n  featureId: string,\n  currentUsageData: FeatureUsageRecord,\n  now: number\n) {\n  try {\n    const oldValue = localStorage.getItem(STORAGE_KEY)\n    const storedUsageData = oldValue\n      ? (JSON.parse(oldValue) as FeatureUsageRecord)\n      : {}\n    const mergedUsageData = applyPendingUsage(storedUsageData)\n    const usageData = {\n      ...mergedUsageData,\n      [featureId]: incrementUsage(\n        latestUsage(mergedUsageData[featureId], currentUsageData[featureId]),\n        now\n      )\n    }\n    const newValue = JSON.stringify(usageData)\n\n    localStorage.setItem(STORAGE_KEY, newValue)\n    pendingUsage.clear()\n    window.dispatchEvent(\n      new StorageEvent('storage', {\n        key: STORAGE_KEY,\n        oldValue,\n        newValue,\n        storageArea: localStorage\n      })\n    )\n    return usageData\n  } catch {\n    return\n  }\n}\n\n/**\n * Tracks feature usage for survey eligibility.\n * Persists to localStorage.\n */\nexport function useFeatureUsageTracker(featureId: string) {\n  const usageData = useStorage<FeatureUsageRecord>(STORAGE_KEY, {})\n\n  const usage = computed(() => usageData.value[featureId])\n  const useCount = computed(() => usage.value?.useCount ?? 0)\n\n  function trackUsage() {\n    const now = Date.now()\n    const currentUsageData = usageData.value\n    const existing = currentUsageData[featureId]\n\n    const persistedUsageData = persistUsageData(\n      featureId,\n      currentUsageData,\n      now\n    )\n    const nextUsageData = persistedUsageData ?? {\n      ...currentUsageData,\n      [featureId]: incrementUsage(\n        latestUsage(pendingUsage.get(featureId), existing),\n        now\n      )\n    }\n    if (!persistedUsageData) {\n      const nextUsage = nextUsageData[featureId]\n      if (nextUsage) pendingUsage.set(featureId, nextUsage)\n    }\n    usageData.value = nextUsageData\n  }\n\n  function reset() {\n    delete usageData.value[featureId]\n    pendingUsage.delete(featureId)\n  }\n\n  return {\n    usage,\n    useCount,\n    trackUsage,\n    reset\n  }\n}\n"],"mappings":"yIAMA,IAAa,EAAuD,CAClE,cAAe,CACb,UAAW,cACX,WAAY,WACZ,iBAAkB,EAClB,QAAS,GACX,EACA,yBAA0B,CACxB,UAAW,yBACX,WAAY,WACZ,iBAAkB,GAClB,QAAS,GACX,EACA,cAAe,CACb,UAAW,cACX,WAAY,WACZ,iBAAkB,EAClB,aAAc,YAChB,EACA,oBAAqB,CACnB,UAAW,oBACX,WAAY,WACZ,iBAAkB,EAClB,QAAS,GACX,CACF,EAEA,SAAgB,gBACd,EACiC,CACjC,OAAO,EAAgB,EACzB,CAEA,SAAgB,mBAA2C,CACzD,OAAO,OAAO,OAAO,CAAe,CAAC,CAAC,OACnC,GAAW,EAAO,UAAY,EACjC,CACF,CAMA,SAAgB,oBAA4C,CAC1D,OAAO,kBAAkB,CAAC,CAAC,OACxB,IAAY,EAAO,cAAgB,cAAgB,UACtD,CACF,CC1CA,IAAM,EAAc,qBACd,EAAe,IAAI,IAEzB,SAAS,YACP,EACA,EACA,CAGA,OAFK,EACA,EACE,EAAY,UAAY,EAAa,SACxC,EACA,EAHsB,EADD,CAK3B,CAEA,SAAS,eACP,EACA,EACc,CACd,MAAO,CACL,UAAW,GAAO,UAAY,GAAK,EACnC,UAAW,GAAO,WAAa,EAC/B,SAAU,CACZ,CACF,CAEA,SAAS,kBAAkB,EAA+B,CACxD,MAAO,CACL,GAAG,EACH,GAAG,OAAO,YACR,CAAC,GAAG,CAAY,CAAC,CAAC,KAAK,CAAC,EAAW,KAAW,CAC5C,EACA,YAAY,EAAU,GAAY,CAAK,CACzC,CAAC,CACH,CACF,CACF,CAEA,SAAS,iBACP,EACA,EACA,EACA,CACA,GAAI,CACF,IAAM,EAAW,aAAa,QAAQ,CAAW,EAI3C,EAAkB,kBAHA,EACnB,KAAK,MAAM,CAAQ,EACpB,CAAC,CACoD,EACnD,EAAY,CAChB,GAAG,GACF,GAAY,eACX,YAAY,EAAgB,GAAY,EAAiB,EAAU,EACnE,CACF,CACF,EACM,EAAW,KAAK,UAAU